// C implementation of vstodo cmdLsRemote header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_ls_remote.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_ls_remote.go.\n\n#ifndef VSTODO_C_CMD_LS_REMOTE_H\n#define VSTODO_C_CMD_LS_REMOTE_H\n\n// List references from a remote repository.\n// Equivalent to Go cmdLsRemote function.\n// app — vstodo application context pointer\n// args — remote URL arguments\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_ls_remote(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_LS_REMOTE_H